const stages=[['01 / CODE','Version-controlled changes and practical Python and Bash automation, grounded in Linux and networking fundamentals.'],['02 / BUILD & VALIDATE','Reusable workflows, quality checks, and validation before release. Shared patterns make delivery easier to maintain.'],['03 / DEPLOY','Repeatable infrastructure. Controlled releases. A clear path back when a deployment needs to roll back.'],['04 / OBSERVE & IMPROVE','Metrics, logs, and actionable alerts support incident response, root-cause analysis, and continuous improvement.']];
document.querySelectorAll('[data-stage]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-stage]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');const stage=stages[Number(button.dataset.stage)];document.querySelector('#stage-number').textContent=stage[0];document.querySelector('#stage-detail').textContent=stage[1]}));
const skills={platform:['01 / CLOUD & PLATFORM','Repeatable foundations.','Provisioning and operating cloud infrastructure, containers, and Kubernetes across Azure, AWS, and GCP.',['Azure / AKS','AWS / EKS','GCP / GKE','Terraform','Docker','Helm','IAM & RBAC','Networking'],'Provisioning · Configuration · Access controls · Deployment'],delivery:['02 / DELIVERY & AUTOMATION','A clearer path to production.','Building and modernising CI/CD with reusable workflows, quality checks, phased migration, and controlled releases.',['GitHub Actions','Jenkins','Bamboo','GitLab CI/CD','Harness','Argo CD','Flux CD','Python & Bash','SonarQube','Artifactory'],'Build · Validate · Promote · Roll back'],reliability:['03 / RELIABILITY & SYSTEMS','Understand. Respond. Improve.','Operating Linux systems and cloud workloads, tuning alerts, coordinating incidents, and documenting root causes.',['Prometheus','Grafana','Datadog','Splunk','Azure Monitor','CloudWatch','Linux','Ansible','Incident response','RCA'],'Monitor · Diagnose · Recover · Learn']};
const tabs=[...document.querySelectorAll('[data-skill]')];function selectSkill(button){tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1});const s=skills[button.dataset.skill];const panel=document.querySelector('#skill-panel');panel.setAttribute('aria-labelledby',button.id);panel.innerHTML=`<span class="panel-index">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p><div class="skill-tags">${s[3].map(t=>`<span>${t}</span>`).join('')}</div><p class="panel-note">${s[4]}</p>`}tabs.forEach((button,i)=>{button.addEventListener('click',()=>selectSkill(button));button.addEventListener('keydown',e=>{let index;if(['ArrowRight','ArrowDown'].includes(e.key))index=(i+1)%tabs.length;else if(['ArrowLeft','ArrowUp'].includes(e.key))index=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();tabs[index].focus();selectSkill(tabs[index])})});
const stories={migration:{title:'Modernising a 13,000+ plan CI/CD estate.',intro:'At Capgemini, I led the assessment and phased migration of approximately 13,000 Bamboo build plans to GitHub Actions.',sections:[['The approach',['Assessed the existing build estate and introduced reusable workflows and composite actions.','Used self-hosted runners and integrated build, quality, and artefact tooling.','Validated builds in parallel and used phased cutover with rollback controls.']],['Reported outcomes',['No release disruption during the migration.','Approximately 20% lower pipeline-maintenance effort.']],['Engineering focus',['Reusable delivery patterns, migration validation, and controlled change at scale.']]]},platform:{title:'Consistent delivery across cloud platforms.',intro:'My platform work spans AKS, EKS, and GKE, with repeatable provisioning and delivery across development, test, and production.',sections:[['My contribution',['Designed provisioning and delivery patterns using Terraform and Helm.','Used Argo CD and Flux CD for GitOps practices.','Supported 2 to 7 deployments daily through controlled delivery processes.']],['Earlier foundations',['At Persistent Systems, provisioned AWS and Azure services and managed Docker and Kubernetes deployments.','Automated Linux and middleware configuration with Ansible and Puppet.']],['Engineering focus',['Consistency across environments, access controls, troubleshooting, and maintainable infrastructure.']]]},reliability:{title:'Making production signals more actionable.',intro:'At Capgemini, I improved production visibility and reduced recurring alert noise by approximately 60% through alert tuning and operational analysis.',sections:[['My contribution',['Worked with Prometheus, Grafana, Datadog, Splunk, AppDynamics, CloudWatch, and Azure Monitor.','Owned major-incident bridges, stakeholder updates, and root-cause analysis as a shift lead.','Led a 10-member operations team and trained more than 21 engineers.']],['Systems background',['At Nielsen, administered Linux systems within an approximately 8,000-server estate.','Handled patching, service health, access, storage, and network troubleshooting.']],['Engineering focus',['Actionable monitoring, clear incident communication, and reducing recurring operational issues.']]]}};
const dialog=document.querySelector('#case-dialog');let opener;document.querySelectorAll('[data-case]').forEach(button=>button.addEventListener('click',()=>{opener=button;const s=stories[button.dataset.case];document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">${s.title}</h2><p>${s.intro}</p>${s.sections.map(([title,items])=>`<h3>${title}</h3><ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul>`).join('')}`;dialog.showModal();document.body.classList.add('modal-open')}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});
const menu=document.querySelector('.menu');const navigation=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open)});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{navigation.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){navigation.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('v.gopal.mannuru@gmail.com');status.textContent='Email address copied'}catch{status.textContent='Please copy: v.gopal.mannuru@gmail.com'}});
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.case,.section-heading,.skill-panel,.timeline article').forEach(el=>observer.observe(el))}
